def hids_to_policies(apps, schema_editor):
    """Списки разрешённых машин по hid становятся политикой входа на этот профиль: источники называются хостами."""
    Machine = apps.get_model("machines", "Machine")
    Profile = apps.get_model("machines", "MachineProfile")
    Hid = apps.get_model("machines", "MachineProfileHID")
    Policy = apps.get_model("machines", "EntryPolicy")
    names = {machine.hid: machine.hostname or machine.name for machine in Machine.objects.all()}
    for profile in Profile.objects.all():
        hids = list(Hid.objects.filter(profile=profile).values_list("hid", flat=True))
        if not hids:
            continue
        policy = Policy.objects.create(name=f"{profile.login}@{profile.machine_id}: источники", sources="\n".join(names.get(hid, hid) for hid in hids))
        Profile.objects.filter(pk=profile.pk).update(entry_policy=policy)


